<?php
/**
 * Front-end output driven by Theme Options: header, footer, blog display and extras.
 *
 * Header and footer replace the `header` / `footer` template parts at render
 * time (unless "built by: Site Editor" is chosen). Blog toggles hide blocks
 * marked with `wpm-*` class names in the templates.
 *
 * Generated by DEVOUR.
 */

if (!defined('ABSPATH')) {
	exit;
}

final class WPM_Frontend {

	/** Template block class => [blog section, option]. */
	const BLOG_TOGGLES = [
		'wpm-list-image'      => ['list', 'show_image'],
		'wpm-list-date'       => ['list', 'show_date'],
		'wpm-list-author'     => ['list', 'show_author'],
		'wpm-list-cats'       => ['list', 'show_categories'],
		'wpm-single-image'    => ['single', 'show_image'],
		'wpm-single-date'     => ['single', 'show_date'],
		'wpm-single-author'   => ['single', 'show_author'],
		'wpm-single-cats'     => ['single', 'show_categories'],
		'wpm-single-tags'     => ['single', 'show_tags'],
		'wpm-single-nav'      => ['single', 'post_nav'],
		'wpm-single-comments' => ['single', 'comments'],
	];

	public static function boot() {
		add_filter('render_block', [__CLASS__, 'render_block'], 10, 2);
		add_filter('render_block_data', [__CLASS__, 'block_data']);
		add_action('widgets_init', [__CLASS__, 'register_widget_areas']);
		add_action('wp_footer', [__CLASS__, 'back_to_top']);
		add_action('init', [__CLASS__, 'maybe_disable_emojis']);
	}

	/* ---------------------------------------------------------- utilities */

	private static function classes(array $block) {
		$class = $block['attrs']['className'] ?? '';
		return $class === '' ? [] : preg_split('/\s+/', trim($class));
	}

	/** Render a single block from name + attributes. */
	private static function block($name, array $attrs = []) {
		return do_blocks(sprintf('<!-- wp:%s %s /-->', $name, serialize_block_attributes($attrs)));
	}

	/* ------------------------------------------------------ block filters */

	public static function render_block($content, $block) {
		$name = $block['blockName'] ?? '';

		if ($name === 'core/template-part') {
			$slug = $block['attrs']['slug'] ?? '';
			if ($slug === 'header' && WPM_Options::get('header', 'general', 'source') === 'options') {
				return self::header();
			}
			if ($slug === 'footer' && WPM_Options::get('footer', 'general', 'source') === 'options') {
				return self::footer();
			}
			return $content;
		}

		foreach (self::classes($block) as $class) {
			if (isset(self::BLOG_TOGGLES[$class])) {
				list($section, $option) = self::BLOG_TOGGLES[$class];
				if (!WPM_Options::flag('blog', $section, $option)) {
					return '';
				}
			}
			$show = WPM_Options::get('blog', 'list', 'content');
			if (($class === 'wpm-list-excerpt' && $show !== 'excerpt') || ($class === 'wpm-list-content' && $show !== 'full')) {
				return '';
			}
		}
		return $content;
	}

	public static function block_data($block) {
		$classes = self::classes($block);
		$list    = WPM_Options::all()['blog']['list'];
		$grid    = strpos($list['layout'], 'grid-') === 0;

		if (in_array('wpm-post-list', $classes, true)) {
			$block['attrs']['layout'] = $grid
				? ['type' => 'grid', 'columnCount' => (int) substr($list['layout'], 5)]
				: ['type' => 'default'];
		} elseif (in_array('wpm-list-excerpt', $classes, true)) {
			$block['attrs']['excerptLength'] = (int) $list['excerpt_length'];
			$block['attrs']['moreText']      = $list['read_more'];
		} elseif (in_array('wpm-list-image', $classes, true) && $grid) {
			$block['attrs']['aspectRatio'] = '16/9';
		}
		return $block;
	}

	/* ------------------------------------------------------------- header */

	private static function social_links() {
		$links  = '';
		$social = WPM_Options::all()['footer']['social'];
		foreach (WPM_Options::SOCIAL as $service => $label) {
			if ($social[$service] !== '') {
				$links .= sprintf('<!-- wp:social-link %s /-->', serialize_block_attributes([
					'url'     => $social[$service],
					'service' => $service,
					'label'   => $label,
				]));
			}
		}
		if ($links === '') {
			return '';
		}
		return do_blocks(
			'<!-- wp:social-links {"className":"is-style-logos-only wpm-social"} -->'
			. '<ul class="wp-block-social-links is-style-logos-only wpm-social">' . $links . '</ul>'
			. '<!-- /wp:social-links -->'
		);
	}

	private static function show_social($where) {
		$position = WPM_Options::get('footer', 'social', 'position');
		return $position === $where || $position === 'both';
	}

	/**
	 * Render a navigation block for a menu option value ('0', 'c:ID' classic menu, 'n:ID' Site Editor menu).
	 * '0' falls back to the menu assigned to the location in Appearance → Menus, then to
	 * the automatic page list (header) or nothing (footer).
	 */
	private static function navigation($value, array $attrs, $location, $automatic) {
		$value = WPM_Options::valid_menu($value) ?? '0';
		if ($value === '0') {
			$locations = get_nav_menu_locations();
			if (!empty($locations[$location]) && is_nav_menu($locations[$location])) {
				$value = 'c:' . (int) $locations[$location];
			}
		}

		if (strpos($value, 'c:') === 0) {
			$menu  = wp_get_nav_menu_object((int) substr($value, 2));
			$inner = $menu ? WP_Classic_To_Block_Menu_Converter::convert($menu) : '';
			if (is_string($inner) && $inner !== '') {
				return do_blocks('<!-- wp:navigation ' . serialize_block_attributes($attrs) . ' -->' . $inner . '<!-- /wp:navigation -->');
			}
			return ''; // empty menu: show nothing rather than an unexpected page list
		}
		if (strpos($value, 'n:') === 0) {
			$attrs['ref'] = (int) substr($value, 2);
			return self::block('navigation', $attrs);
		}
		return $automatic ? self::block('navigation', $attrs) : '';
	}

	private static function brand() {
		$o    = WPM_Options::all()['header']['logo'];
		$home = esc_url(home_url('/'));
		$name = get_bloginfo('name');
		$html = '';

		$logo = (int) $o['image'];
		if ($logo) {
			$img = wp_get_attachment_image($logo, 'full', false, [
				'alt'      => $name,
				'loading'  => 'eager',
				'decoding' => 'async',
				'class'    => 'wpm-logo__img',
			]);
			if ($img) {
				$html .= '<a class="wpm-logo" href="' . $home . '" rel="home">' . $img . '</a>';
			}
		}

		if ($o['show_title'] === '1' || $html === '') {
			$tag   = is_front_page() && is_home() ? 'h1' : 'p';
			$html .= sprintf(
				'<%1$s class="wp-block-site-title wpm-site-title"><a href="%2$s" rel="home">%3$s</a></%1$s>',
				$tag, $home, esc_html($name)
			);
		}
		if ($o['show_tagline'] === '1' && get_bloginfo('description') !== '') {
			$html .= '<p class="wpm-site-tagline">' . esc_html(get_bloginfo('description')) . '</p>';
		}
		return '<div class="wpm-header__brand">' . $html . '</div>';
	}

	public static function header() {
		$h = WPM_Options::all()['header'];

		$classes = [
			'wp-block-template-part',
			'wpm-site-header',
			'wpm-header--logo-' . $h['general']['logo_position'],
			'wpm-header--width-' . $h['general']['width'],
		];
		if ($h['general']['border'] === '1') {
			$classes[] = 'wpm-header--border';
		}
		if ($h['sticky']['enabled'] === '1') {
			$classes[] = 'wpm-header--sticky';
			if ($h['sticky']['shrink'] === '1') {
				$classes[] = 'wpm-header--shrink';
			}
		}

		$topbar = '';
		if ($h['topbar']['enabled'] === '1' && $h['topbar']['text'] !== '') {
			$text   = esc_html($h['topbar']['text']);
			$text   = $h['topbar']['link'] !== '' ? '<a href="' . esc_url($h['topbar']['link']) . '">' . $text . '</a>' : $text;
			$topbar = '<div class="wpm-topbar"><div class="wpm-container">' . $text . '</div></div>';
		}

		$position = $h['general']['logo_position'];
		$nav      = self::navigation($h['menu']['menu'], [
			'className'           => 'wpm-header-nav',
			'overlayMenu'         => $h['menu']['mobile'],
			'openSubmenusOnClick' => $h['menu']['submenu'] === 'click',
			'layout'              => [
				'type'           => 'flex',
				'justifyContent' => $position === 'center' ? 'center' : ($position === 'right' ? 'left' : 'right'),
			],
		], 'header', true);

		$actions = '';
		if ($h['extras']['search'] === '1') {
			$actions .= self::block('search', [
				'label'               => 'Search',
				'showLabel'           => false,
				'buttonText'          => 'Search',
				'buttonPosition'      => 'button-only',
				'buttonUseIcon'       => true,
				'isSearchFieldHidden' => true,
				'className'           => 'wpm-header-search',
			]);
		}
		if (self::show_social('header')) {
			$actions .= self::social_links();
		}
		if ($h['extras']['cta_text'] !== '' && $h['extras']['cta_url'] !== '') {
			$target   = $h['extras']['cta_new_tab'] === '1' ? ' target="_blank" rel="noopener"' : '';
			$actions .= sprintf(
				'<a class="wp-element-button wpm-header-cta" href="%s"%s>%s</a>',
				esc_url($h['extras']['cta_url']), $target, esc_html($h['extras']['cta_text'])
			);
		}

		return sprintf(
			'<header class="%s">%s<div class="wpm-header__bar"><div class="wpm-container wpm-header__inner">%s<div class="wpm-header__nav">%s</div>%s</div></div></header>',
			esc_attr(implode(' ', $classes)),
			$topbar,
			self::brand(),
			$nav,
			$actions !== '' ? '<div class="wpm-header__actions">' . $actions . '</div>' : ''
		);
	}

	/* ------------------------------------------------------------- footer */

	/**
	 * All six areas are always registered so widgets are never orphaned when the
	 * column count changes; the description says which ones are currently shown.
	 */
	public static function register_widget_areas() {
		$shown = (int) WPM_Options::get('footer', 'widgets', 'columns');
		for ($i = 1; $i <= WPM_Options::FOOTER_WIDGET_AREAS; $i++) {
			register_sidebar([
				'id'            => 'footer-' . $i,
				'name'          => 'Footer column ' . $i,
				'description'   => $i <= $shown
					? sprintf('Shown in the footer widget row (column %d of %d).', $i, $shown)
					: sprintf('Not shown: Theme Options → Footer → Widget columns is %d.', $shown),
				'before_widget' => '<section id="%1$s" class="widget %2$s">',
				'after_widget'  => '</section>',
				'before_title'  => '<h2 class="widget-title">',
				'after_title'   => '</h2>',
			]);
		}
	}

	private static function widget_row() {
		$columns = (int) WPM_Options::get('footer', 'widgets', 'columns');
		if ($columns < 1) {
			return '';
		}
		$preview = WPM_Options::is_preview();
		$cells   = '';
		$filled  = false;
		for ($i = 1; $i <= $columns; $i++) {
			$content = '';
			if (is_active_sidebar('footer-' . $i)) {
				ob_start();
				dynamic_sidebar('footer-' . $i);
				$content = ob_get_clean();
				$filled  = true;
			} elseif ($preview) {
				$content = sprintf('<p class="wpm-widget-placeholder">Footer column %d<br><small>Add widgets in Appearance → Widgets</small></p>', $i);
			}
			$cells .= '<div class="wpm-footer-widgets__col">' . $content . '</div>';
		}
		if (!$filled && !$preview) {
			return ''; // nothing to show yet
		}
		return sprintf(
			'<div class="wpm-footer-widgets wpm-footer-widgets--cols-%1$d"><div class="wpm-container wpm-footer-widgets__grid" style="--wpm-footer-cols:%1$d">%2$s</div></div>',
			$columns,
			$cells
		);
	}

	public static function footer() {
		$f = WPM_Options::all()['footer']['general'];

		$copyright = strtr($f['copyright'], [
			'{year}'       => esc_html(wp_date('Y')),
			'{site_title}' => esc_html(get_bloginfo('name')),
		]);

		$menu = self::navigation($f['menu'], [
			'className'   => 'wpm-footer-nav',
			'overlayMenu' => 'never',
			'layout'      => ['type' => 'flex', 'justifyContent' => 'center', 'flexWrap' => 'wrap'],
		], 'footer', false);

		$social  = self::show_social('footer') ? self::social_links() : '';
		$powered = $f['powered_by'] === '1'
			? '<p class="wpm-powered">Proudly powered by <a href="https://wordpress.org">WordPress</a></p>'
			: '';

		return sprintf(
			'<footer class="wp-block-template-part wpm-site-footer">%s<div class="wpm-footer__bar"><div class="wpm-container wpm-footer__inner"><div class="wpm-footer__copy">%s</div>%s%s%s</div></div></footer>',
			self::widget_row(),
			wpautop(wp_kses_post($copyright)),
			$menu,
			$social,
			$powered
		);
	}

	/* ------------------------------------------------------------- extras */

	public static function back_to_top() {
		if (WPM_Options::flag('advanced', 'general', 'back_to_top')) {
			echo '<button type="button" class="wpm-back-to-top wp-element-button" aria-label="Back to top" hidden>↑</button>';
		}
	}

	public static function maybe_disable_emojis() {
		if (!WPM_Options::flag('advanced', 'general', 'disable_emojis')) {
			return;
		}
		remove_action('wp_head', 'print_emoji_detection_script', 7);
		remove_action('wp_print_styles', 'print_emoji_styles');
		remove_action('wp_enqueue_scripts', 'wp_enqueue_emoji_styles');
		remove_filter('the_content_feed', 'wp_staticize_emoji');
		remove_filter('comment_text_rss', 'wp_staticize_emoji');
		remove_filter('wp_mail', 'wp_staticize_emoji_for_email');
		add_filter('emoji_svg_url', '__return_false');
	}
}
